// prettier-ignore
export const GUIDE_HTML: string = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"referrer\" content=\"no-referrer\">\n<meta name=\"theme-color\" content=\"#1f6feb\">\n<meta name=\"color-scheme\" content=\"light dark\">\n<link rel=\"manifest\" href=\"/manifest.webmanifest\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<title>Manager guide</title>\n<link rel=\"stylesheet\" href=\"/app.css\">\n</head>\n<body class=\"guide-page\">\n<header class=\"guide-top\"><strong>NanoClaw Manager</strong><span class=\"muted\">Guide</span><a class=\"back\" href=\"/\">&larr; Back to the panel</a></header>\n<div class=\"guide-wrap\">\n<nav class=\"guide-toc\" aria-label=\"Contents\">\n<a class=\"toc-2\" href=\"#what-you-get\">What you get</a>\n<a class=\"toc-2\" href=\"#how-it-fits-together\">How it fits together</a>\n<a class=\"toc-2\" href=\"#installing\">Installing</a>\n<a class=\"toc-3\" href=\"#installing-from-scratch\">Installing from scratch</a>\n<a class=\"toc-3\" href=\"#requirements\">Requirements</a>\n<a class=\"toc-3\" href=\"#applying-the-skills\">Applying the skills</a>\n<a class=\"toc-3\" href=\"#after-installing-the-upgrade-check\">After installing: the upgrade check</a>\n<a class=\"toc-2\" href=\"#first-run\">First run</a>\n<a class=\"toc-3\" href=\"#create-the-administrator\">Create the administrator</a>\n<a class=\"toc-2\" href=\"#reaching-the-panel\">Reaching the panel</a>\n<a class=\"toc-3\" href=\"#https-and-network-access\">HTTPS and network access</a>\n<a class=\"toc-2\" href=\"#using-the-dashboard\">Using the dashboard</a>\n<a class=\"toc-3\" href=\"#using-it-on-a-phone\">Using it on a phone</a>\n<a class=\"toc-3\" href=\"#overview\">Overview</a>\n<a class=\"toc-3\" href=\"#agents\">Agents</a>\n<a class=\"toc-3\" href=\"#model\">Model</a>\n<a class=\"toc-3\" href=\"#phone\">Phone</a>\n<a class=\"toc-3\" href=\"#backups\">Backups</a>\n<a class=\"toc-2\" href=\"#models\">Models</a>\n<a class=\"toc-3\" href=\"#connecting-an-endpoint\">Connecting an endpoint</a>\n<a class=\"toc-3\" href=\"#the-small-model\">The small model</a>\n<a class=\"toc-3\" href=\"#images-photos-from-the-phone-app\">Images (photos from the phone app)</a>\n<a class=\"toc-3\" href=\"#api-keys\">API keys</a>\n<a class=\"toc-3\" href=\"#ollama\">Ollama</a>\n<a class=\"toc-3\" href=\"#chatgpt\">ChatGPT</a>\n<a class=\"toc-3\" href=\"#claude\">Claude</a>\n<a class=\"toc-3\" href=\"#removing-a-credential\">Removing a credential</a>\n<a class=\"toc-3\" href=\"#how-a-model-change-works\">How a model change works</a>\n<a class=\"toc-3\" href=\"#endpoint-checks-and-errors\">Endpoint checks and errors</a>\n<a class=\"toc-2\" href=\"#backups-1\">Backups</a>\n<a class=\"toc-3\" href=\"#what-a-backup-contains\">What a backup contains</a>\n<a class=\"toc-3\" href=\"#the-backup-key\">The backup key</a>\n<a class=\"toc-3\" href=\"#consistency-levels\">Consistency levels</a>\n<a class=\"toc-3\" href=\"#retention-and-pruning\">Retention and pruning</a>\n<a class=\"toc-3\" href=\"#scheduled-backups\">Scheduled backups</a>\n<a class=\"toc-3\" href=\"#restoring-a-backup\">Restoring a backup</a>\n<a class=\"toc-3\" href=\"#rehearsal-restore\">Rehearsal restore</a>\n<a class=\"toc-3\" href=\"#moving-to-another-machine\">Moving to another machine</a>\n<a class=\"toc-2\" href=\"#the-phone-app\">The phone app</a>\n<a class=\"toc-3\" href=\"#setting-it-up\">Setting it up</a>\n<a class=\"toc-3\" href=\"#the-phone-page\">The Phone page</a>\n<a class=\"toc-3\" href=\"#security\">Security</a>\n<a class=\"toc-2\" href=\"#terminal-only-tasks\">Terminal-only tasks</a>\n<a class=\"toc-3\" href=\"#forgotten-password\">Forgotten password</a>\n<a class=\"toc-3\" href=\"#channels-and-agents\">Channels and agents</a>\n<a class=\"toc-3\" href=\"#updating-nanoclaw\">Updating NanoClaw</a>\n<a class=\"toc-3\" href=\"#rebuilding-agent-images\">Rebuilding agent images</a>\n<a class=\"toc-3\" href=\"#removing-the-skills\">Removing the skills</a>\n<a class=\"toc-2\" href=\"#security-model\">Security model</a>\n<a class=\"toc-2\" href=\"#troubleshooting\">Troubleshooting</a>\n<a class=\"toc-2\" href=\"#reference\">Reference</a>\n<a class=\"toc-3\" href=\"#settings\">Settings</a>\n<a class=\"toc-3\" href=\"#terminal-commands\">Terminal commands</a>\n<a class=\"toc-3\" href=\"#files-and-folders\">Files and folders</a>\n<a class=\"toc-3\" href=\"#http-api\">HTTP API</a>\n<a class=\"toc-2\" href=\"#known-limits\">Known limits</a>\n</nav>\n<main class=\"guide\">\n<h1 id=\"manager-guide\">Manager guide<a class=\"anchor\" href=\"#manager-guide\" aria-label=\"Link to this section\">#</a></h1>\n<p>How to install, run and look after a NanoClaw install with the <strong>manager</strong> skills: the web panel (<code>add-manager-panel</code>) and encrypted backups (<code>add-manager-backup</code>).</p>\n<p>This guide is also served by the panel itself at <code>/guide</code>, and the panel links to the sections below wherever something can only be done from a terminal.</p>\n<blockquote><p><strong>Unofficial.</strong> These skills are not part of NanoClaw and are not affiliated with its authors. They attach to upstream NanoClaw through its own extension points and change one line of its source (<code>src/modules/index.ts</code>).</p></blockquote>\n<h2 id=\"what-you-get\">What you get<a class=\"anchor\" href=\"#what-you-get\" aria-label=\"Link to this section\">#</a></h2>\n<div class=\"table-wrap\"><table><tbody><tr><td><strong>Web panel</strong></td><td>Overview, agents (restart), one OpenAI-compatible model endpoint for every agent, backups. Password login, English interface.</td></tr><tr><td><strong>Backups</strong></td><td>Encrypted single-file backups of the whole install, verification, restore with rollback, a rehearsal mode for testing a backup on another machine.</td></tr><tr><td><strong>Terminal tools</strong></td><td><code>scripts/manager-backup.ts</code> and <code>scripts/manager-panel.ts</code>, for everything the panel deliberately does not do.</td></tr></tbody></table></div>\n<p>What the panel does <strong>not</strong> do, on purpose: restore a backup, change passwords without a terminal, store API keys, install channels, update NanoClaw. Those are in <a href=\"#terminal-only-tasks\">Terminal-only tasks</a>.</p>\n<h2 id=\"how-it-fits-together\">How it fits together<a class=\"anchor\" href=\"#how-it-fits-together\" aria-label=\"Link to this section\">#</a></h2>\n<pre><code> browser ──HTTP(S)──▶ panel (inside the NanoClaw host process)\n                         │  reads/writes .env and each group's config\n                         │  restarts agent containers\n                         └─ backup library ──▶ encrypted files in the backups folder\n\n terminal ─▶ scripts/manager-backup.ts   create / verify / restore / commit / rollback / prune\n          └▶ scripts/manager-panel.ts    setup-code / reset-password / unlock / status</code></pre>\n<ul><li>The panel is a <strong>module of the NanoClaw host</strong>: it starts and stops with it. It has the same privileges as the NanoClaw user, so protect access to it like a shell on the machine.</li><li>Models are not run by NanoClaw. Agents call an <strong>OpenAI-compatible HTTP endpoint</strong> you provide (a local server such as llama.cpp or vLLM, or a hosted provider) through upstream's OpenCode provider (<code>add-opencode</code>).</li><li>Credentials for model providers live in the <strong>credential gateway</strong> (OneCLI by default), never in <code>.env</code> and never in a backup.</li></ul>\n<h2 id=\"installing\">Installing<a class=\"anchor\" href=\"#installing\" aria-label=\"Link to this section\">#</a></h2>\n<h3 id=\"installing-from-scratch\">Installing from scratch<a class=\"anchor\" href=\"#installing-from-scratch\" aria-label=\"Link to this section\">#</a></h3>\n<p>On a fresh Debian 13 machine (an LXC needs nesting for Docker), as root and in a real terminal (a console or <code>ssh -t</code>), not through a chat:</p>\n<pre><code class=\"language-bash\">git clone https://github.com/olac-acul/skills-for-nanoclaw.git\nbash skills-for-nanoclaw/install.sh</code></pre>\n<p>It goes through these steps, asking on the way:</p>\n<ol><li><strong>System:</strong> a few packages, Bun (the version the agent containers use), the user NanoClaw runs as (<code>nanoclaw</code>; <code>--user NAME</code> for another), its user services allowed to run without a login, and passwordless sudo for the duration of the installation, which upstream's installer needs.</li><li><strong>Code:</strong> NanoClaw at its newest stable release, on the branch <code>main</code>, and a copy of this repository in the user's home (the update command lives there).</li><li><strong>NanoClaw's own installer</strong> (<code>nanoclaw.sh</code>): Node, Docker, the model provider, the credential gateway, the time zone, the assistant and the first channel. For an OpenAI-compatible server choose OpenCode, then <em>Local or self-hosted</em>; for the gateway choose OneCLI. Tokens and keys go only into its prompts.</li><li><strong>These skills:</strong> backups and the panel always, the voice channel if you use the NanoVoice app. They are applied with NanoClaw's own skill engine (<code>scripts/install-skills.mjs</code>), which builds and runs their tests.</li><li><strong>The panel:</strong> where it listens (only this machine, one of the machine's addresses, for example a VPN one, or every address), then the one-time setup code for the administrator.</li><li><strong>Weekly backups:</strong> day, time and how many to keep; the backup key is shown once, to store in a password manager (see <a href=\"#scheduled-backups\">Scheduled backups</a>).</li><li><strong>The voice channel</strong> (if chosen): which agent answers the app, and the address it listens on. Then pair the phone with the QR of the panel's Phone page.</li><li><strong>Extra skills:</strong> with <code>--extra DIR</code>, each <code>DIR/&lt;skill&gt;/setup.sh</code> is offered and run (for example private skills of your own with an interactive setup).</li><li><strong>Finishing:</strong> the passwordless sudo is taken away again, if you agree.</li></ol>\n<p>Two things it watches for: a first run of NanoClaw's installer can stop while installing the credential gateway (<em>&quot;OneCLI installer did not report its URL&quot;</em>), and running it again goes on from there, so the script offers to; and a <code>onecli</code> program already on the machine would make NanoClaw's installer use OneCLI's hosted service instead of a local gateway, so the script offers to move it aside first.</p>\n<p>Each step is recorded in <code>/var/lib/nanoclaw-installer/</code> when it is done. If one stops, fix the cause and run the same command again: it goes on from there. <code>--redo STEP</code> runs one step again (<code>base</code>, <code>code</code>, <code>upstream</code>, <code>skills</code>, <code>panel</code>, <code>backups</code>, <code>voice</code>, <code>extras</code>, <code>finish</code>).</p>\n<h3 id=\"requirements\">Requirements<a class=\"anchor\" href=\"#requirements\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li>A working NanoClaw install, version 2.4 or later, with Docker. See upstream's README.</li><li>The credential gateway skill (<code>add-onecli</code>) and the OpenCode provider (<code>add-opencode</code>) installed with upstream's own skills. The panel only writes the settings those read.</li><li>Node 22 or later and pnpm, as NanoClaw itself needs.</li></ul>\n<p>What was actually tested: Debian 13 in an LXC container, Docker 29, Node 22.23, pnpm 10, Bun 1.4.0, NanoClaw <code>main</code> at the time of writing, OneCLI 1.41.0, applying the skills with upstream's own skill engine. Anything else is expected to work but was not tried.</p>\n<h3 id=\"applying-the-skills\">Applying the skills<a class=\"anchor\" href=\"#applying-the-skills\" aria-label=\"Link to this section\">#</a></h3>\n<p>Get this repository, then copy the two skill folders into the install:</p>\n<pre><code class=\"language-bash\">cp -r skills-for-nanoclaw/.claude/skills/add-manager-backup  ~/nanoclaw/.claude/skills/\ncp -r skills-for-nanoclaw/.claude/skills/add-manager-panel   ~/nanoclaw/.claude/skills/</code></pre>\n<p>Apply them in this order. In Claude Code, from the install folder:</p>\n<pre><code>/add-manager-backup\n/add-manager-panel</code></pre>\n<p>Each skill checks its prerequisites, copies its files, builds, typechecks and runs its tests. The panel skill also appends one line, <code>import './manager-panel/index.js';</code>, to <code>src/modules/index.ts</code>. Both are safe to repeat.</p>\n<p>To apply them without an agent (this is how they are tested), the repository has a script that does it with upstream's own engine on a clean checkout:</p>\n<pre><code class=\"language-bash\">node scripts/compose.mjs --upstream https://github.com/nanocoai/nanoclaw.git</code></pre>\n<h3 id=\"after-installing-the-upgrade-check\">After installing: the upgrade check<a class=\"anchor\" href=\"#after-installing-the-upgrade-check\" aria-label=\"Link to this section\">#</a></h3>\n<p>NanoClaw refuses to start when its files changed outside its own setup or update flow. Installing a skill counts as such a change, and you will see an <em>&quot;upgrade tripwire&quot;</em> message. Once the build and tests of the skills passed, record the new state and start again:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/upgrade-state.ts set</code></pre>\n<p>Then rebuild if you changed code (<code>pnpm run build</code>) and restart the NanoClaw service.</p>\n<h2 id=\"first-run\">First run<a class=\"anchor\" href=\"#first-run\" aria-label=\"Link to this section\">#</a></h2>\n<p>After restarting, the host log says where the panel listens, for example:</p>\n<pre><code>Manager panel listening  bind=127.0.0.1 port=3200 https=false\nManager panel has no administrator yet. Run: pnpm exec tsx scripts/manager-panel.ts setup-code</code></pre>\n<h3 id=\"create-the-administrator\">Create the administrator<a class=\"anchor\" href=\"#create-the-administrator\" aria-label=\"Link to this section\">#</a></h3>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-panel.ts setup-code</code></pre>\n<p>It prints the panel address and a one-time code such as <code>ABCD-EFGH-JKMN-PQRS</code>. Open the address, enter the code and choose a password of at least 12 characters. The code works once and expires after 30 minutes; run the command again for a new one. There is one administrator account.</p>\n<h2 id=\"reaching-the-panel\">Reaching the panel<a class=\"anchor\" href=\"#reaching-the-panel\" aria-label=\"Link to this section\">#</a></h2>\n<p>By default the panel listens on <code>127.0.0.1:3200</code>: only the machine itself can open it. Options:</p>\n<ul><li><strong>From the same machine:</strong> open <code>http://127.0.0.1:3200</code>.</li><li><strong>From another computer, through SSH</strong> (nothing to configure): <code>ssh -L 3200:127.0.0.1:3200 user@the-machine</code>, then open <code>http://127.0.0.1:3200</code> locally.</li><li><strong>From other devices on the local network:</strong> see <a href=\"#https-and-network-access\">HTTPS and network access</a>.</li></ul>\n<h3 id=\"https-and-network-access\">HTTPS and network access<a class=\"anchor\" href=\"#https-and-network-access\" aria-label=\"Link to this section\">#</a></h3>\n<p>Settings go in the install's <code>.env</code> file; restart NanoClaw after changing them.</p>\n<p>To allow other devices on your network:</p>\n<pre><code>PANEL_BIND=0.0.0.0</code></pre>\n<p>Even then, connections from public internet addresses are refused, and the request's <code>Host</code> name must be local: an IP address, <code>localhost</code>, a single-word name, or a name ending in <code>.local</code>, <code>.lan</code>, <code>.internal</code> or <code>.home.arpa</code>. For any other name, list it:</p>\n<pre><code>PANEL_ALLOWED_HOSTS=panel.example.org,nas.mydomain.net</code></pre>\n<p><strong>Without HTTPS</strong> the panel works but shows a warning on every page (except on localhost): your password and backup keys cross the network unencrypted. That can be acceptable on a trusted home network. Choose one of these to encrypt the connection:</p>\n<ol><li><strong>Your own certificate</strong>, served by the panel:\n<pre><code>PANEL_TLS_CERT=/path/to/cert.pem\nPANEL_TLS_KEY=/path/to/key.pem</code></pre>\n<p>The files are read when NanoClaw starts. The panel does not create or renew certificates.</p></li><li><strong>A reverse proxy that terminates TLS.</strong> Keep the panel on localhost, point the proxy at it, and tell the panel the exact address the browser uses:\n<pre><code>PANEL_BIND=127.0.0.1\nPANEL_PUBLIC_ORIGIN=https://panel.example.org\nPANEL_ALLOWED_HOSTS=panel.example.org</code></pre>\n<p>An example for nginx (not tested here; adapt it):</p>\n<pre><code>server {\n  listen 443 ssl;\n  server_name panel.example.org;\n  # ssl_certificate / ssl_certificate_key ...\n  client_max_body_size 0;\n  location / {\n    proxy_pass http://127.0.0.1:3200;\n    proxy_set_header Host $host;\n    proxy_buffering off;\n    proxy_read_timeout 300s;\n  }\n}</code></pre>\n<p>The long read timeout matters: creating a backup can wait for running agents (up to <code>PANEL_BACKUP_WAIT_SECONDS</code>, 60 by default), and downloads can be large.</p></li></ol>\n<p>With HTTPS the session cookie becomes <code>__Host-manager_panel</code> with the <code>Secure</code> flag, and the <code>Strict-Transport-Security</code> header is sent.</p>\n<p>If a page loads but every action fails with <em>origin_mismatch</em>, the address in the browser differs from the one the panel expects: set <code>PANEL_PUBLIC_ORIGIN</code> exactly to what the address bar shows (scheme, name and port, no trailing slash).</p>\n<h2 id=\"using-the-dashboard\">Using the dashboard<a class=\"anchor\" href=\"#using-the-dashboard\" aria-label=\"Link to this section\">#</a></h2>\n<p>Sign in with the administrator password. Sessions end after 30 minutes without activity or 8 hours in total. Wrong passwords are counted <strong>per address</strong> (a whole <code>/64</code> for IPv6): five are free, then every further failure from that address doubles a lock (one minute, two, four, up to an hour), so one device on the network cannot lock the administrator out from another. A high overall ceiling (50 failures in an hour, kept across restarts) still stops a flood from many addresses; a valid session can always confirm its password, even then. Sensitive actions (applying a model, creating, downloading or deleting a backup) ask for the password again if you have not typed it in the last five minutes.</p>\n<h3 id=\"using-it-on-a-phone\">Using it on a phone<a class=\"anchor\" href=\"#using-it-on-a-phone\" aria-label=\"Link to this section\">#</a></h3>\n<p>The panel adapts to a small screen: the four pages are a tab bar at the bottom, within reach of a thumb; tables become one card per agent or backup; fields and buttons are large enough to tap; dialogs open from the bottom edge. It follows the phone's light or dark setting.</p>\n<p>To put it on the home screen, open the panel in the phone's browser, then:</p>\n<ul><li><strong>iPhone or iPad (Safari):</strong> Share, then <strong>Add to Home Screen</strong>.</li><li><strong>Android (Chrome):</strong> the menu, then <strong>Add to Home screen</strong> (or <strong>Install app</strong>).</li></ul>\n<p>It then opens without the browser's address bar, with its own icon. Over plain HTTP on a local network the phone treats this as a shortcut, and some phones still show the address bar; over HTTPS (<a href=\"#https-and-network-access\">HTTPS and network access</a>) Android offers a real install. The icon is drawn by the panel itself, nothing is downloaded from outside. A home-screen copy keeps its own sign-in, separate from the browser's, so you sign in once in it.</p>\n<h3 id=\"overview\">Overview<a class=\"anchor\" href=\"#overview\" aria-label=\"Link to this section\">#</a></h3>\n<p>Release, how many agents exist and how many are working, sessions, uptime, the credential gateway, installed channels and providers, and the number and date of backups.</p>\n<h3 id=\"agents\">Agents<a class=\"anchor\" href=\"#agents\" aria-label=\"Link to this section\">#</a></h3>\n<p>One row per agent: provider, model and whether it is working. <strong>Restart</strong> stops the agent's containers; the next message starts a fresh one with the current settings. Adding, wiring and removing agents is not done here: see <a href=\"#channels-and-agents\">Channels and agents</a>.</p>\n<h3 id=\"model\">Model<a class=\"anchor\" href=\"#model\" aria-label=\"Link to this section\">#</a></h3>\n<p>The page shows the endpoint and model all agents use. See <a href=\"#models\">Models</a> for how to use it.</p>\n<h3 id=\"phone\">Phone<a class=\"anchor\" href=\"#phone\" aria-label=\"Link to this section\">#</a></h3>\n<p>Whether the NanoVoice app is connected, the address it uses, the token, and the voice channel's on/off switch. See <a href=\"#the-phone-app\">The phone app</a>.</p>\n<h3 id=\"backups\">Backups<a class=\"anchor\" href=\"#backups\" aria-label=\"Link to this section\">#</a></h3>\n<p>The list of backups with date, size, release and consistency, and the actions Verify, Download and Delete. See <a href=\"#backups\">Backups</a>. Restoring is not offered here: see <a href=\"#restoring-a-backup\">Restoring a backup</a>.</p>\n<h2 id=\"models\">Models<a class=\"anchor\" href=\"#models\" aria-label=\"Link to this section\">#</a></h2>\n<p>The <strong>Model</strong> page sets one provider for every agent. Three kinds are offered:</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Provider</th><th>What it is</th><th>Credential</th></tr></thead><tbody><tr><td><strong>OpenAI-compatible endpoint</strong></td><td>Any server that speaks the OpenAI API: a local model server, <a href=\"#ollama\">Ollama</a>, or a hosted service. Agents use OpenCode.</td><td>None for most local servers; a key for hosted ones (<a href=\"#api-keys\">API keys</a>)</td></tr><tr><td><strong><a href=\"#chatgpt\">ChatGPT</a></strong></td><td>OpenAI models through your ChatGPT subscription or an OpenAI API key. Agents use OpenCode.</td><td>Subscription login or API key</td></tr><tr><td><strong><a href=\"#claude\">Claude</a></strong></td><td>Anthropic models through the Claude provider NanoClaw ships with.</td><td>API key or Claude subscription token</td></tr></tbody></table></div>\n<p>Choosing a provider and pressing <strong>Apply</strong> changes every agent at once, with the same rollback as described in <a href=\"#how-a-model-change-works\">How a model change works</a>. The page shows which provider is in use.</p>\n<h3 id=\"connecting-an-endpoint\">Connecting an endpoint<a class=\"anchor\" href=\"#connecting-an-endpoint\" aria-label=\"Link to this section\">#</a></h3>\n<p>An endpoint is the base URL of an OpenAI-compatible API, ending in <code>/v1</code>, for example <code>http://model-server:8000/v1</code> or <code>https://api.example-provider.com/v1</code>.</p>\n<ol><li>Open <strong>Model</strong>. Enter the endpoint and the model name exactly as the server lists it.</li><li>Press <strong>Check endpoint</strong>. The panel asks the server for its model list, confirms your model is in it, and sends a one-token test request. The list becomes the suggestions of the model field.</li><li>If the check passed, <strong>Apply to all agents</strong> becomes available. It asks for your password.</li></ol>\n<p>Rules the panel enforces on the address:</p>\n<ul><li>Loopback, private-network (home or office LAN, VPN) and unique-local addresses may use plain HTTP.</li><li>A public address must use HTTPS.</li><li>Link-local addresses (including cloud metadata services), multicast and reserved ranges are refused.</li><li>No credentials, query string or fragment in the URL.</li></ul>\n<p>From inside the agent containers the machine running NanoClaw is reachable at the Docker bridge address (shown by <code>docker network inspect bridge</code>, usually the first one in the 172.17 range) or at <code>host.docker.internal</code>; <code>localhost</code> inside a container is the container itself. A model server on the same machine as NanoClaw therefore needs an address such as <code>http://&lt;bridge-address&gt;:8000/v1</code> and must listen on that interface, not only on <code>127.0.0.1</code>.</p>\n<h3 id=\"the-small-model\">The small model<a class=\"anchor\" href=\"#the-small-model\" aria-label=\"Link to this section\">#</a></h3>\n<p>OpenCode, the provider that talks to the endpoint, can use a second, lighter model for minor background work. The field <strong>Small model (optional)</strong> sets it. Leave it empty to use the main model for everything, which is the right choice when you run a single model. The panel does not check that the small model exists on the endpoint; a wrong name shows up when OpenCode first tries to use it.</p>\n<h3 id=\"images-photos-from-the-phone-app\">Images (photos from the phone app)<a class=\"anchor\" href=\"#images-photos-from-the-phone-app\" aria-label=\"Link to this section\">#</a></h3>\n<p>The box <strong>The model understands images</strong> tells NanoClaw that the model can receive pictures. It matters for the NanoVoice app: a photo sent from the phone reaches the model only when the box is on, and a model that cannot see images would otherwise answer as if the photo were not there. It is stored as <code>OPENCODE_MODEL_INPUT_MODALITIES</code> in <code>.env</code> (the panel adds or removes <code>image</code> and leaves other entries such as <code>pdf</code> alone).</p>\n<ul><li><strong>Endpoint:</strong> when you check an endpoint, the panel reads what the server says about the model. Some servers (OpenRouter and others) list the input types, and then the box is set for you with a note saying so. Most OpenAI-compatible servers say nothing; the box then keeps its value and you tick it if you know the model sees images. The panel never guesses from the model's name.</li><li><strong>ChatGPT:</strong> the box starts on, because the ChatGPT models take images. Turn it off if yours does not.</li><li><strong>Claude:</strong> not used; Claude handles images by itself.</li></ul>\n<p>A change made here is covered by the same rollback as the rest of a model change.</p>\n<h3 id=\"api-keys\">API keys<a class=\"anchor\" href=\"#api-keys\" aria-label=\"Link to this section\">#</a></h3>\n<p>Model providers' keys and tokens are kept in the <strong>credential gateway</strong> (OneCLI), never in <code>.env</code> and never in a backup. There are two ways to put one there:</p>\n<ul><li><strong>In the panel.</strong> On the ChatGPT and Claude forms, paste the key and press <strong>Save</strong>. The password is asked again first. The value goes from your browser to the panel, to a helper process, to the gateway, and is never shown or returned again. Saving again replaces the stored value and keeps the agents' access to it.</li><li><strong>From a terminal</strong>, with upstream's tool, which also covers keys for a hosted OpenAI-compatible service:\n<pre><code class=\"language-bash\">pnpm exec tsx setup/index.ts --step provider-auth opencode</code></pre>\n<p>Choose the local or self-hosted option, enter the endpoint and, when asked, the key.</p></li></ul>\n<blockquote><p><strong>Over plain HTTP a key crosses your network in clear text</strong> when you paste it into the panel. The panel warns about this on every page except localhost. Use localhost, an SSH tunnel or <a href=\"#https-and-network-access\">HTTPS</a> when you enter secrets.</p></blockquote>\n<p>Entering keys in the panel needs the OpenCode and OneCLI skills installed (<code>add-opencode</code>, <code>add-onecli</code>) because the helper that stores them is built on those. Without them the panel says so and simply does not offer ChatGPT or Claude credentials.</p>\n<p>A <em>401</em> result from <strong>Check endpoint</strong> (<em>the endpoint wants an API key</em>) means the key is missing or the endpoint is not the one the key was stored for.</p>\n<h3 id=\"ollama\">Ollama<a class=\"anchor\" href=\"#ollama\" aria-label=\"Link to this section\">#</a></h3>\n<p><a href=\"https://ollama.com\" target=\"_blank\" rel=\"noopener noreferrer\">Ollama</a> runs models on your own machine and speaks the OpenAI API at <code>http://&lt;address&gt;:11434/v1</code>. The panel uses it as an OpenAI-compatible endpoint; no key is needed.</p>\n<ol><li>Install Ollama and pull a model that supports tool calls, for example <code>ollama pull &lt;model&gt;</code>. Agents use tools heavily, and models without reliable tool use do poorly.</li><li>Make Ollama reachable <strong>from the agent containers</strong>. By default it listens on <code>127.0.0.1</code> only, which a container cannot reach. Set <code>OLLAMA_HOST=&lt;bridge address&gt;:11434</code> in Ollama's service environment and restart it (the Docker bridge address is what <strong>Use Ollama</strong> shows; <code>0.0.0.0</code> also works but opens the port to your network). Remember to set the same <code>OLLAMA_HOST</code> when you run <code>ollama pull</code>.</li><li>On the <strong>Model</strong> page choose <em>OpenAI-compatible endpoint</em> and press <strong>Use Ollama</strong>. It fills in the Docker bridge address of this machine with port 11434 and checks it; the models you pulled appear as suggestions in the <strong>Model</strong> field.</li><li>Pick a model, <strong>Check endpoint</strong>, then <strong>Apply to all agents</strong>.</li></ol>\n<p><strong>Ollama on another machine.</strong> Type its address in the <strong>Endpoint</strong> field instead of pressing <strong>Use Ollama</strong>: <code>http://&lt;address&gt;:11434/v1</code>, then <strong>Check endpoint</strong> and <strong>Apply</strong>. This is the usual setup with a GPU server. On that machine, make Ollama listen on a reachable address (<code>OLLAMA_HOST=0.0.0.0:11434</code>, or one interface's address) and allow port 11434 through its firewall. Ollama has no login, so expose it only on a network you trust, or put a reverse proxy with HTTPS and authentication in front. The panel accepts plain HTTP for private and local addresses and requires HTTPS for anything else. The agent containers reach the address through the credential gateway like any other endpoint; in a test, the check from one machine and a real agent request from its container both reached an Ollama on another machine this way.</p>\n<p><strong>Speed.</strong> An agent's first request carries about 2,000 tokens of instructions. On a CPU-only machine a 3-billion-parameter model reads them at roughly 40 tokens a second, so even a small model needs a minute or more before it starts to answer, and more again to write the reply. A GPU, or a hosted endpoint, is the practical choice for day-to-day use. The first <strong>Check endpoint</strong> can also be slow, because the model is loaded into memory by that first request; for a model on this machine the panel waits up to two minutes for it.</p>\n<p><strong>Model size.</strong> In a test on a CPU-only machine, <code>qwen2.5:3b</code> took about ten minutes to answer a greeting, and the answer was not in the format agents must use (a <code>&lt;message to=&quot;...&quot;&gt;</code> block), so nothing was delivered: it talked about creating a directory it had no reason to touch. The pipeline (panel, endpoint, agent, model) worked; the model was too small and too slow for an agent. Expect to need a much larger model and a GPU for useful results.</p>\n<p><strong>Context window.</strong> Ollama's default window is 4,096 tokens (<code>OLLAMA_CONTEXT_LENGTH</code> in its service environment raises it). Agents with long conversations or many tools need more; if answers stop following the instructions, raise it. Ollama does not report the window to the panel, so the panel leaves the context limits unset for it.</p>\n<p>NanoClaw's own skill for Ollama (<code>add-ollama-provider</code>) takes a different route: it points the Claude provider at Ollama's Anthropic-style API and edits each agent's container settings. The panel does not use it. The two should not be combined.</p>\n<h3 id=\"chatgpt\">ChatGPT<a class=\"anchor\" href=\"#chatgpt\" aria-label=\"Link to this section\">#</a></h3>\n<p>Agents reach OpenAI through OpenCode, with the credential injected by the gateway. Two ways to authenticate:</p>\n<ul><li><strong>Subscription login.</strong> Press <strong>Sign in with ChatGPT</strong> (the password is asked again). The panel starts OpenCode's device pairing in a short-lived container and shows a page and a code. Open the page, sign in to ChatGPT there and enter the code. The panel waits up to 15 minutes and stores the login in the gateway, which refreshes it by itself. <strong>Cancel</strong> stops the attempt.</li><li><strong>API key.</strong> Paste an OpenAI API key and press <strong>Save</strong>.</li></ul>\n<p>Then enter the <strong>model name exactly as OpenAI names it</strong>, optionally a small model, and press <strong>Apply</strong>. The panel cannot check the name: the credential lives in the gateway and cannot be read back to ask OpenAI. A wrong name shows up the first time an agent tries to use it.</p>\n<p>What Apply writes: <code>OPENCODE_PROVIDER=openai</code>, <code>OPENCODE_BASE_URL=native</code>, <code>OPENCODE_MODEL</code> and <code>OPENCODE_SMALL_MODEL</code> as <code>openai/&lt;name&gt;</code>, and for a subscription login <code>OPENCODE_AUTH_MODE=chatgpt</code> (removed for an API key). Any context limits from an earlier endpoint are removed.</p>\n<p>The sign-in needs Docker (it runs OpenCode in a container) and the agent image built with the OpenCode provider.</p>\n<h3 id=\"claude\">Claude<a class=\"anchor\" href=\"#claude\" aria-label=\"Link to this section\">#</a></h3>\n<p>This is the provider NanoClaw ships with (the Claude Agent SDK), not OpenCode. Its credential is an <strong>Anthropic API key</strong> or a <strong>Claude subscription token</strong>. For a subscription, run <code>claude setup-token</code> in a terminal, sign in as it asks, and paste the token it prints into the panel. <strong>Save</strong> stores it in the gateway as the secret named <em>Anthropic</em> for <code>api.anthropic.com</code>, replacing a previous one.</p>\n<p>Applying Claude sets every agent's provider back to the default (Claude) and, if you enter one, its model; leave the model empty to use the provider's default. The <code>OPENCODE_*</code> settings are left alone, so switching back to an endpoint later is one step.</p>\n<p>As with ChatGPT, the panel cannot check a model name against Anthropic. Use the full name Anthropic gives (for example <code>claude-haiku-4-5-20251001</code>); a short or invented name such as <code>haiku-4.5</code> makes every agent answer with <em>There's an issue with the selected model</em>.</p>\n<p><strong>A note on replacing a Claude key.</strong> When a key is already stored, the panel replaces it in place, which keeps the secret's identity and the agents' access to it. The gateway's command line only accepts the new value as an argument, so for the fraction of a second the call lasts the value is visible to other users of the same machine through the process list. On a machine only you use this does not matter; on a shared one, enter the key with a person-only terminal tool or remove the credential first and save it again (a new secret is created through a private file, never on a command line). The panel only touches a secret of type <em>Anthropic</em> or named exactly <em>Anthropic</em>.</p>\n<h3 id=\"removing-a-credential\">Removing a credential<a class=\"anchor\" href=\"#removing-a-credential\" aria-label=\"Link to this section\">#</a></h3>\n<p>Next to each stored credential there is a <strong>Remove</strong> button (click it twice, then confirm your password). It deletes the secret from the gateway: the ChatGPT login, the OpenAI key (the secret named <em>OpenCode openai</em>) or the Anthropic one. The panel refuses while the agents are using that credential, so switch to another provider first. Removing something that is already gone is not an error. Removing a ChatGPT login here does not sign you out of ChatGPT itself; revoke an API key on the provider's own site as well if you no longer want it to work.</p>\n<h3 id=\"how-a-model-change-works\">How a model change works<a class=\"anchor\" href=\"#how-a-model-change-works\" aria-label=\"Link to this section\">#</a></h3>\n<p>Applying a change (an endpoint, ChatGPT or Claude) does this, in order:</p>\n<ol><li>Checks the endpoint again.</li><li>Writes a <strong>journal</strong> with the previous <code>.env</code> values and every agent's previous provider and model.</li><li>Writes the <code>OPENCODE_*</code> settings to <code>.env</code>: for an endpoint, <code>OPENCODE_PROVIDER</code>, <code>OPENCODE_BASE_URL</code>, <code>OPENCODE_MODEL</code>, <code>OPENCODE_SMALL_MODEL</code> and, when the server reports its context window, <code>OPENCODE_MODEL_CONTEXT_LIMIT</code> and <code>OPENCODE_MODEL_OUTPUT_LIMIT</code> (half the window, at most 4096), and <code>OPENCODE_MODEL_INPUT_MODALITIES</code> when you made an image choice; for ChatGPT the settings listed in <a href=\"#chatgpt\">ChatGPT</a>; for Claude nothing.</li><li>Sets every agent group's provider and model: <code>opencode</code> and <code>openai/&lt;model&gt;</code>, or the default provider (Claude) with the model you gave.</li><li>Verifies what was written, then restarts every agent.</li><li>Deletes the journal.</li></ol>\n<p>If anything fails before the restarts, or NanoClaw stops in the middle, everything is put back from the journal (automatically at the next start in the second case). A restart that fails after the change was written does not undo it: the affected agents pick the settings up the next time they start. Running turns are interrupted by the restarts.</p>\n<p>Both limits are written together or not at all because OpenCode rejects a context limit without an output limit.</p>\n<h3 id=\"endpoint-checks-and-errors\">Endpoint checks and errors<a class=\"anchor\" href=\"#endpoint-checks-and-errors\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Message</th><th>What it means and what to do</th></tr></thead><tbody><tr><td><em>Could not reach the endpoint</em></td><td>Wrong address or port, server down, firewall, or the server listens only on <code>127.0.0.1</code>.</td></tr><tr><td><em>The endpoint does not list that model</em></td><td>The model name differs from what <code>/v1/models</code> returns. Pick one from the suggestions.</td></tr><tr><td><em>The endpoint wants an API key</em></td><td>See <a href=\"#api-keys\">API keys</a>.</td></tr><tr><td><em>Plain HTTP is only accepted for local addresses</em></td><td>Use HTTPS for a public host, or a local address.</td></tr><tr><td><em>That address is not allowed</em></td><td>Link-local, multicast, cloud metadata or other reserved address, including NAT64, 6to4 and Teredo forms.</td></tr><tr><td><em>The name could not be resolved</em></td><td>DNS does not know the host name from the NanoClaw machine.</td></tr><tr><td><em>The TLS certificate could not be verified</em></td><td>Self-signed or expired certificate on an HTTPS endpoint.</td></tr><tr><td><em>The endpoint did not answer like an OpenAI-compatible API</em></td><td>The URL is not the API root (often missing <code>/v1</code>).</td></tr><tr><td><em>The model did not answer a test request</em></td><td>The server lists the model but fails on a completion; check its log.</td></tr><tr><td><em>The change failed and the previous settings were restored</em></td><td>Something broke while applying; nothing changed. Check the NanoClaw log.</td></tr></tbody></table></div>\n<h2 id=\"backups-1\">Backups<a class=\"anchor\" href=\"#backups-1\" aria-label=\"Link to this section\">#</a></h2>\n<h3 id=\"what-a-backup-contains\">What a backup contains<a class=\"anchor\" href=\"#what-a-backup-contains\" aria-label=\"Link to this section\">#</a></h3>\n<p>One encrypted file holding:</p>\n<ul><li>the central database (a consistent snapshot);</li><li>every agent's session data, including each conversation's databases (snapshotted safely);</li><li>agent group folders (memory, files, plugins) and channel stores;</li><li>the <code>.env</code> file and the allowlists in <code>~/.config/nanoclaw</code>;</li><li>a manifest: release, applied migrations, which skills and gateway were installed, counts.</li></ul>\n<p>Left out: sockets and lock files, per-run scratch data, logs, container images (rebuilt after a restore), and the machine's own identity files unless you ask for them (<code>--machine-identity</code>).</p>\n<p><strong>The phone app's voice channel</strong> (<code>add-voice</code>): a full restore brings back its token, switch and port (<code>VOICE_*</code> in <code>.env</code>) and the phone's wake-up address (<code>data/voice-push.json</code>), so a paired phone keeps working. Two things are not part of a backup: the channel's live state (<code>data/voice-status.json</code>, who is connected now) and a pairing code that is waiting for a phone (<code>data/voice-pairing.json</code>), which would otherwise be usable on whatever machine the backup lands on. The address the channel listens on (<code>VOICE_BIND_HOST</code>) belongs to the machine, like the gateway address: a restore keeps the one this machine has, and a machine with none starts with the channel on <code>127.0.0.1</code> until you set it (see <a href=\"#the-phone-app\">The phone app</a>).</p>\n<p><strong>Not included: the credentials in the credential gateway.</strong> After restoring onto a new machine, install the gateway skill and enter the credentials again. The manifest lists which skills and gateway the backup came from.</p>\n<h3 id=\"the-backup-key\">The backup key<a class=\"anchor\" href=\"#the-backup-key\" aria-label=\"Link to this section\">#</a></h3>\n<p>Each backup gets its own random 256-bit key, shown <strong>once</strong>, when the backup is created, as 64 hexadecimal characters in groups of eight. It is not stored anywhere, not even in the panel. Put it in a password manager. Without the key the backup cannot be opened, by anyone.</p>\n<p>The key is needed to verify, restore and inspect a backup, never to list or delete one. In the panel, <strong>Verify</strong> asks for the key; the terminal commands read it from the <code>MANAGER_BACKUP_KEY</code> environment variable, from <code>--key-file &lt;path&gt;</code>, or from a hidden prompt, never from a command-line argument.</p>\n<h3 id=\"consistency-levels\">Consistency levels<a class=\"anchor\" href=\"#consistency-levels\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Level</th><th>Meaning</th></tr></thead><tbody><tr><td><code>cold</code></td><td>NanoClaw was stopped. Everything is from the same instant.</td></tr><tr><td><code>quiescent</code></td><td>NanoClaw was running but no agent was working on a message.</td></tr><tr><td><code>best-effort</code></td><td>An agent was working. Each database file is still consistent, but files were not copied at the same instant.</td></tr></tbody></table></div>\n<p>From the panel, <strong>Create backup</strong> starts the backup in the background and shows how it is going. It first waits (up to 60 seconds by default, <code>PANEL_BACKUP_WAIT_SECONDS</code>) for agents that are in the middle of a turn, so the copy is as consistent as possible. Agents that are alive but idle do not count. When the wait is over the backup <strong>goes ahead anyway</strong>; the result says whether it is <code>quiescent</code> or <code>best-effort</code>. Then the panel shows the backup's <strong>key, once</strong>: store it before closing the window. A backup of several gigabytes takes minutes; you can leave the page and come back, and it picks up where things stand (a key that nobody collected within 15 minutes is dropped and the backup has to be repeated). Only one backup runs at a time.</p>\n<h3 id=\"retention-and-pruning\">Retention and pruning<a class=\"anchor\" href=\"#retention-and-pruning\" aria-label=\"Link to this section\">#</a></h3>\n<p>Backups accumulate in the backups folder (<code>~/.local/share/nanoclaw-backups/&lt;install&gt;</code> by default, or <code>PANEL_BACKUP_DIR</code> / <code>MANAGER_BACKUP_DIR</code>). The panel can delete single backups; to keep the newest few and one per month:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts prune --keep-last 7 --keep-monthly 6</code></pre>\n<p>Keep copies on <strong>another disk or machine</strong>: a backup next to the data it protects does not protect against losing the disk. A downloaded or copied <code>.mbk</code> file is all you need besides its key.</p>\n<p>Backups from the panel need the panel's reauthentication and a person to save the key. For backups nobody has to start, see <a href=\"#scheduled-backups\">Scheduled backups</a>.</p>\n<h3 id=\"scheduled-backups\">Scheduled backups<a class=\"anchor\" href=\"#scheduled-backups\" aria-label=\"Link to this section\">#</a></h3>\n<p>A weekly backup that runs by itself, from a systemd timer of the install's user. Run these in the install folder, as the NanoClaw user:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts schedule init-key\npnpm exec tsx scripts/manager-backup.ts schedule install --keep 3 --weekday Sun --time 03:30\nsudo loginctl enable-linger &quot;$USER&quot;      # once: lets the timer run without a login</code></pre>\n<ul><li><strong>The key.</strong> Nobody is there to save a different key each week, so scheduled backups share <strong>one key of their own</strong>. <code>init-key</code> creates it, prints it <strong>once</strong> (store a copy in a password manager) and keeps it in <code>~/.config/nanoclaw/scheduled-backup.key</code>, readable by you only, outside the backups folder. Anyone who has that key and a backup can open the backup, so if a backup leaves this machine, take the key's copy with you separately. Without the key a scheduled backup cannot be opened, so losing it loses them all. <code>init-key</code> never replaces an existing key.</li><li><strong>What a run does.</strong> It waits up to five minutes for agents that are in the middle of a message, then backs up anyway (the backup says whether it was <code>quiescent</code> or <code>best-effort</code>), then deletes scheduled backups beyond the newest <code>--keep</code>. <strong>Manual backups are never deleted by it.</strong> It refuses to start when the disk is too full for another backup, and keeps the older ones if a new one fails.</li><li><strong>When.</strong> The time is the machine's local time, with up to ten minutes of random delay. If the machine was off at that time, the backup runs at the next start (<code>Persistent</code>).</li><li><strong>Look at it.</strong> <code>schedule status</code> shows the key, the timer, the next run and the scheduled backups kept. The log of a run is in the journal: <code>journalctl --user -u nanoclaw-backup-&lt;install&gt;.service</code>. The panel marks scheduled backups with a <em>Scheduled</em> label.</li><li><strong>Restore.</strong> Use the scheduled key like any other: <code>restore &lt;id&gt; --key-file ~/.config/nanoclaw/scheduled-backup.key</code>, or paste it from the password manager on another machine.</li><li><strong>Disk space.</strong> Each backup is about the size of the install's data. With <code>--keep 3</code> plan for four copies at the moment a new one is being written. Copy backups to <strong>another disk or machine</strong> too.</li><li><strong>Stop it.</strong> <code>schedule remove</code> removes the timer and leaves the key file and the backups.</li></ul>\n<h3 id=\"restoring-a-backup\">Restoring a backup<a class=\"anchor\" href=\"#restoring-a-backup\" aria-label=\"Link to this section\">#</a></h3>\n<p>Restoring is <strong>terminal-only</strong> and needs NanoClaw <strong>stopped</strong>: it replaces the data the running host is using. Stop the service first (and the agent containers, which keep running on their own), then:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts list\npnpm exec tsx scripts/manager-backup.ts restore &lt;id&gt;</code></pre>\n<p>The command asks for the key, authenticates the whole file before touching anything, prints what it will do, and asks you to type <code>RESTORE</code>. Then it:</p>\n<ol><li>unpacks into a staging area next to the live data;</li><li>swaps <code>data/</code>, <code>groups/</code> and <code>store/</code> by moving their contents (a symlinked or mounted folder keeps its identity), keeping the old state for rollback;</li><li>writes <code>.env</code>, keeping this machine's own <code>ONECLI_*</code>, <code>NANOCLAW_GATEWAY_PROVIDER</code>, <code>PANEL_*</code> and <code>no_proxy</code> settings;</li><li>prepares the database for a clean start: sessions marked stopped, host leases and session claims cleared, derived image tags cleared.</li></ol>\n<p>Facts to know:</p>\n<ul><li>A backup <strong>older</strong> than the installed code is restored, and NanoClaw applies the newer migrations at its next start. A backup <strong>newer</strong> than the installed code is refused: update NanoClaw first.</li><li>This install's own upgrade marker is kept, so the startup check does not trip.</li><li><strong>The gateway selection.</strong> If this machine has no credential gateway selected in <code>.env</code> (an install that did not finish its setup) and the backup's gateway skill is installed here, the restore sets <code>NANOCLAW_GATEWAY_PROVIDER</code> to the backup's value and says so. A machine that already selects a gateway keeps its own choice; if it differs from the backup's, the restore warns.</li><li><strong>Credentials to enter again.</strong> Gateway credentials are not in a backup, but their <strong>names</strong> are (never the values). The restore lists the ones this machine does not have yet, for example <code>OpenCode openai, Anthropic</code>; enter them again in the panel (Model page) or with the gateway's own tools. A backup made while the gateway could not be asked has no list.</li><li><strong>Only the known settings files are restored</strong> from <code>~/.config/nanoclaw</code> (the mount and sender allowlists; the machine's identity files only with <code>--machine-identity</code>). The restore prints which it replaced and which it left alone, and it never writes <code>scheduled-backup.key</code>. Review a replaced <code>mount-allowlist.json</code> before starting: it decides which folders agent containers may see.</li><li><strong>Links.</strong> A restored <code>data/</code>, <code>db/</code>, <code>env/</code> or <code>config/</code> tree may only hold links that stay inside it; <code>groups/</code> and <code>store/</code> may hold any link (agents' own environments), and nothing in a restore follows them. Run restores as the install's user, not as <code>root</code>.</li><li><strong>One at a time.</strong> A restore, a rollback or a commit takes a lock; a second one started meanwhile is refused (<code>restore_in_progress</code>). Transaction ids are checked (<code>YYYYMMDDTHHMMSSZ-xxxxxx</code>).</li><li><strong>If it is interrupted.</strong> The journal is written before each step. A crash leaves a transaction in the state <code>swapping</code>: <code>commit</code> refuses it and <code>rollback &lt;transaction&gt;</code> puts the previous state back from the copies kept on disk, without deleting anything until the originals are back. If the automatic rollback itself fails you get <code>rollback_failed</code> and the transaction stays: fix the cause (permissions, disk) and run <code>rollback &lt;transaction&gt;</code> again.</li><li>Everything newer than the backup (messages, memory, tasks) is replaced. The rollback copy is the only way back.</li><li>Agent groups whose container image was customised are listed; rebuild them with <code>ncl groups restart --id &lt;group&gt; --rebuild</code>.</li></ul>\n<p>Start NanoClaw and check that it works. Then either keep the result or undo it:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-backup.ts commit &lt;transaction&gt;     # delete the rollback copy\npnpm exec tsx scripts/manager-backup.ts rollback &lt;transaction&gt;   # put everything back</code></pre>\n<p>The transaction id is printed by <code>restore</code>. If the restore fails part way, it rolls itself back. After <code>commit</code> or <code>rollback</code> only the last transaction's small journal stays in <code>.manager-backup-txn/</code>, so that repeating the command can say what already happened.</p>\n<h3 id=\"rehearsal-restore\">Rehearsal restore<a class=\"anchor\" href=\"#rehearsal-restore\" aria-label=\"Link to this section\">#</a></h3>\n<p><code>restore &lt;id&gt; --rehearsal</code> restores a copy that <strong>cannot act as the original</strong>. Use it to test a backup on a second machine while the first is still running, without two installs answering the same chats. It:</p>\n<ul><li>keeps only a short allowlist of <code>.env</code> settings (the time zone, log level, container resource limits and image names, the model settings) and drops anything that looks like a token, password, key, cookie or credentialed URL (it prints the names it dropped);</li><li>does not restore channel stores, channel login files or the machine's identity;</li><li>leaves out the whole voice channel: no <code>VOICE_*</code> setting (so no token, and the channel does not start) and no wake-up address for the phone, so a rehearsal can neither accept the phone nor wake it;</li><li>marks pending tasks as paused, closes every pending or in-flight chat message, and marks undelivered replies as not deliverable, so a rehearsal host with a working channel has nothing to send.</li></ul>\n<p>Conversation history, memory and the agents' files are kept. To go live afterwards, do a normal restore (or reinstall the channels' credentials yourself).</p>\n<h3 id=\"moving-to-another-machine\">Moving to another machine<a class=\"anchor\" href=\"#moving-to-another-machine\" aria-label=\"Link to this section\">#</a></h3>\n<ol><li>On the old machine: create a backup (cold, with NanoClaw stopped, if you can) and save the key.</li><li>On the new machine: install NanoClaw, the gateway, the provider and both manager skills, plus the channel skills the backup used (the restore warns about missing ones). Re-enter the gateway credentials.</li><li>Copy the <code>.mbk</code> file into the new backups folder (or pass its path to <code>restore</code>).</li><li>Run a <a href=\"#rehearsal-restore\">rehearsal restore</a> first, check the agents, then restore for real with the old machine stopped, so that two installs never talk to the same accounts.</li></ol>\n<h2 id=\"the-phone-app\">The phone app<a class=\"anchor\" href=\"#the-phone-app\" aria-label=\"Link to this section\">#</a></h2>\n<p><a href=\"https://github.com/olac-acul/nanovoice\" target=\"_blank\" rel=\"noopener noreferrer\">NanoVoice</a> is an Android voice assistant that uses this install as its brain. It talks to NanoClaw through the <strong>voice channel</strong>, which comes from the <code>add-voice</code> skill of this repository: a WebSocket that streams the agent's replies to the phone, lets the agent run actions on it (timers, alarms, calendar changes with approval on the phone, music, notes, photos) and is protected by a token.</p>\n<h3 id=\"setting-it-up\">Setting it up<a class=\"anchor\" href=\"#setting-it-up\" aria-label=\"Link to this section\">#</a></h3>\n<p>Everything that changes the install's structure is done from a terminal, once:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/voice-setup.ts enable --bind &lt;address the phone reaches&gt;\n# restart NanoClaw, then\npnpm exec tsx scripts/voice-setup.ts wire\npnpm exec tsx scripts/voice-setup.ts pair      # prints the address and token for the app</code></pre>\n<p>The skill's own documentation explains the choices: which agent answers (one you already have, which shares its memory and tools with the app, or a separate one for the app alone) and which address to listen on (a VPN or private network the phone reaches, never every address of a machine that faces the internet).</p>\n<h3 id=\"the-phone-page\">The Phone page<a class=\"anchor\" href=\"#the-phone-page\" aria-label=\"Link to this section\">#</a></h3>\n<ul><li><strong>App</strong> shows whether the phone is connected now, since when and in which language, or when it last was.</li><li><strong>Voice channel</strong> shows whether the channel is listening. If the setting in <code>.env</code> and the running channel differ (you turned it on or off, and NanoClaw has not restarted since) the page says a restart is needed.</li><li><strong>Address for the app</strong> is what to enter in the app. If the channel listens on this machine only, or on every address, the page says so instead and tells you what to change (<code>VOICE_BIND_HOST</code>).</li><li><strong>Answers from agent</strong> is the agent the channel is wired to. It says so when there is none yet.</li><li><strong>Wake-up push</strong> says whether the app has registered a place where the server can wake it when it is off.</li><li><strong>Pair the app with a QR code</strong> (after you confirm your password) shows a code that the NanoVoice app scans from Settings, NanoClaw server: it fills in the address and token for you. The code is <strong>not the token</strong>: it is a one-time pairing code that works for five minutes, for one app, and the server keeps only its hash. Five wrong tries cancel it, and making another cancels the first. The page closes the code by itself when the app has paired, and shows when and which phone paired last. Pairing needs the channel to be running, a token and an address the phone can reach (see <strong>Address for the app</strong>).</li><li><strong>Make a new token</strong> creates a new token, stores it and shows it <strong>once</strong>; nobody can read it again afterwards, here or anywhere else in the panel. Use it when you first set up, when the token may have leaked, or when you lose a phone. It ends the app's current connection at once (the channel checks the token at every login and notices when it changes), and the app has to be given the new one. You are asked for your password again first.</li><li><strong>Turn the channel on / off</strong> changes <code>VOICE_ENABLED</code> in <code>.env</code>. It needs a token to turn on, and takes effect the next time NanoClaw starts.</li></ul>\n<h3 id=\"security\">Security<a class=\"anchor\" href=\"#security\" aria-label=\"Link to this section\">#</a></h3>\n<p>The token is a password for the agent and for the phone's actions: anyone who has it can talk to the agent the channel is wired to, with that agent's memory and tools. A plain <code>ws://</code> address sends the token in clear text, which is why the app accepts it only on a private network with a VPN up; elsewhere use a TLS proxy and <code>wss://</code>. The status the channel shares with the panel (<code>data/voice-status.json</code>) holds no secret. The pairing code is exchanged with <code>POST /pair</code> on the voice channel's own address, over the same transport as the rest (plain <code>ws://</code>/<code>http://</code> only on a private network or VPN), and a refusal looks the same whether the code was wrong, expired or never made.</p>\n<h2 id=\"terminal-only-tasks\">Terminal-only tasks<a class=\"anchor\" href=\"#terminal-only-tasks\" aria-label=\"Link to this section\">#</a></h2>\n<p>These are deliberately not in the panel. Each is a short recipe; all commands run in the NanoClaw install folder as the NanoClaw user.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Task</th><th>Where</th></tr></thead><tbody><tr><td>Create the administrator, or get a new setup code</td><td><a href=\"#create-the-administrator\">Create the administrator</a></td></tr><tr><td>Forgot the password, locked out, sign everyone out</td><td><a href=\"#forgotten-password\">Forgotten password</a></td></tr><tr><td>Store or change a model provider's API key (also possible in the panel)</td><td><a href=\"#api-keys\">API keys</a></td></tr><tr><td>Restore a backup, roll back a restore</td><td><a href=\"#restoring-a-backup\">Restoring a backup</a></td></tr><tr><td>Test a backup on another machine</td><td><a href=\"#rehearsal-restore\">Rehearsal restore</a></td></tr><tr><td>Prune old backups</td><td><a href=\"#retention-and-pruning\">Retention and pruning</a></td></tr><tr><td>Back up every week without a person</td><td><a href=\"#scheduled-backups\">Scheduled backups</a></td></tr><tr><td>Open the panel to the network or enable HTTPS</td><td><a href=\"#https-and-network-access\">HTTPS and network access</a></td></tr><tr><td>Add channels and agents</td><td><a href=\"#channels-and-agents\">Channels and agents</a></td></tr><tr><td>Update NanoClaw</td><td><a href=\"#updating-nanoclaw\">Updating NanoClaw</a></td></tr><tr><td>Rebuild an agent's image</td><td><a href=\"#rebuilding-agent-images\">Rebuilding agent images</a></td></tr><tr><td>Uninstall</td><td><a href=\"#removing-the-skills\">Removing the skills</a></td></tr></tbody></table></div>\n<h3 id=\"forgotten-password\">Forgotten password<a class=\"anchor\" href=\"#forgotten-password\" aria-label=\"Link to this section\">#</a></h3>\n<p>From a terminal on the machine:</p>\n<pre><code class=\"language-bash\">pnpm exec tsx scripts/manager-panel.ts reset-password   # asks twice, hidden; signs everyone out\npnpm exec tsx scripts/manager-panel.ts unlock           # clear the lock after too many wrong passwords\npnpm exec tsx scripts/manager-panel.ts revoke-sessions  # sign every browser out\npnpm exec tsx scripts/manager-panel.ts status           # address, administrator set up?, failed logins</code></pre>\n<p>Whoever can run these has the same access as the NanoClaw user, so this is the recovery path and also the reason to keep the machine itself protected.</p>\n<h3 id=\"channels-and-agents\">Channels and agents<a class=\"anchor\" href=\"#channels-and-agents\" aria-label=\"Link to this section\">#</a></h3>\n<p>The panel shows the channels that are installed and the agents that exist; it does not create them. Use upstream's tools: the setup wizard, <code>/manage-channels</code>, <code>/add-telegram</code>, <code>/add-signal</code> and the other <code>/add-*</code> skills in Claude Code, <code>scripts/init-first-agent.ts</code>, and the <code>ncl</code> command-line tool (<code>bin/ncl groups ...</code>). Follow upstream's documentation for those. After installing a channel skill, restart NanoClaw; the new channel shows on the panel's Overview.</p>\n<h3 id=\"updating-nanoclaw\">Updating NanoClaw<a class=\"anchor\" href=\"#updating-nanoclaw\" aria-label=\"Link to this section\">#</a></h3>\n<p>Use the update command of this repository. It drives upstream's own transactional updater (staging copy, snapshot, migrations, health check, automatic way back) and adds what that updater cannot know about the skills here. Run it as the user that owns the install, from a checkout of this repository, in two steps:</p>\n<pre><code class=\"language-bash\">node scripts/update-install.mjs prepare --install ~/nanoclaw      # changes nothing that runs\nnode scripts/update-install.mjs cutover --install ~/nanoclaw      # the step with downtime; it asks first</code></pre>\n<p><code>prepare</code> commits the install's local changes (the skills) as one baseline commit, because upstream's updater needs a clean tree; prepares the update in a separate copy (by default the newest stable release; <code>--channel edge</code> follows upstream's <code>main</code>); settles a merge that conflicts only in lock files by rebuilding them; refreshes this repository's skills in the copy, puts the panel's import line in its place and checks that the voice channel's core changes still fit; then builds and runs the whole test suite there. Whatever fails, the install is untouched. If the merge conflicts in anything else, it stops and says where.</p>\n<p><code>cutover</code> stops the service and the agents' containers, rebuilds the image if upstream's change needs it, and starts again; plan for several minutes without the assistant. If the release asks for the OneCLI gateway to be moved to a pinned version (a security fix, for example), it does that too with a database dump first, as upstream's guide says. Any other requirement stops it with the text, to be done by hand or with upstream's <code>/update-nanoclaw</code>. <code>status</code> shows what is prepared and <code>abandon</code> drops it. Create a backup first (panel or terminal); the update also leaves a git tag and a snapshot of <code>.env</code>, <code>data/</code>, <code>groups/</code> and <code>store/</code> for the way back.</p>\n<p>Needs <code>jq</code> (upstream's tests use it). Everything runs with <code>umask 022</code>: some of upstream's tests depend on it, and a normal login has 002. A host started by hand (not as a service) is not restarted by upstream's updater: stop it before <code>cutover</code>; the command starts it again.</p>\n<p><strong>Only the skills changed</strong> (NanoClaw has no newer release, so <code>prepare</code> says there is nothing to do): update this repository's checkout and apply them again.</p>\n<pre><code class=\"language-bash\">cd ~/skills-for-nanoclaw &amp;&amp; git pull\nnode scripts/install-skills.mjs --install ~/nanoclaw</code></pre>\n<p>Skills already installed are refreshed (their files and dependencies replaced) and then checked, built and tested; the voice section of the agents' instructions is rewritten where it is in use; the new state is recorded and NanoClaw restarts, a few seconds without the assistant. If a test fails it stops before the restart, and the install keeps running the previous build: <code>git status</code> in the install shows what changed and <code>git checkout .</code> undoes it.</p>\n<h3 id=\"rebuilding-agent-images\">Rebuilding agent images<a class=\"anchor\" href=\"#rebuilding-agent-images\" aria-label=\"Link to this section\">#</a></h3>\n<p>Agent groups can have a customised container image (extra packages). Images are not part of a backup. After a restore, or when you change a group's packages:</p>\n<pre><code class=\"language-bash\">bin/ncl groups restart --id &lt;group-id&gt; --rebuild</code></pre>\n<h3 id=\"removing-the-skills\">Removing the skills<a class=\"anchor\" href=\"#removing-the-skills\" aria-label=\"Link to this section\">#</a></h3>\n<p>Each skill has a <code>REMOVE.md</code> that lists exactly what to undo: delete the copied files, delete the one import line from <code>src/modules/index.ts</code>, rebuild. Remove the panel before the backup skill (the panel uses the backup library). Your backups and the <code>data/manager-panel/</code> folder (password hash, audit log) are yours to delete.</p>\n<h2 id=\"security-model\">Security model<a class=\"anchor\" href=\"#security-model\" aria-label=\"Link to this section\">#</a></h2>\n<ul><li>One administrator. The password is hashed with scrypt (memory-hard) and never stored or logged.</li><li>Wrong passwords: five free per address, then a growing lock for that address (it clears when the service restarts, and lasts an hour at most); an overall ceiling of 50 failures an hour, kept across restarts, stops floods. At most three password checks run at once (each costs about 128 MiB), the rest are told to retry.</li><li>Sessions are server-side, in memory (a restart signs everyone out), with an unguessable 256-bit token in an <code>HttpOnly</code>, <code>SameSite=Strict</code> cookie. Over plain HTTP the cookie name carries the port (<code>manager_panel_&lt;port&gt;</code>), because browsers share cookies between ports of the same host name; HTTPS uses the stricter <code>__Host-</code> name. A duplicate cookie is refused rather than guessed at.</li><li>Every request must carry a local <code>Host</code>; cross-site requests are refused; every state change needs the CSRF token <strong>and</strong> an <code>Origin</code> equal to the panel's own.</li><li>Sensitive actions need the password again within the last five minutes.</li><li>Connections from public internet addresses are refused unless <code>PANEL_ALLOW_PUBLIC=true</code>. The panel decides who may connect, and how often, from the address of the TCP connection it sees. <strong>Behind a reverse proxy that address is always the proxy's</strong>, so the &quot;private network only&quot; check and the per-address limits then apply to the proxy and not to your visitors; the same is true of a router that forwards a port. Do not rely on them in that setup: restrict access at the proxy (allowed networks, authentication) and keep the panel bound to the proxy's interface. The panel does not trust <code>X-Forwarded-For</code>, on purpose.</li><li>Responses are built field by field: no credentials, no filesystem paths, no log lines, no internal ids (agents are shown under keyed hashes). Error responses carry a code and a request id only.</li><li>State changes are audited (time, action, status, request id; never bodies) in <code>data/manager-panel/audit.jsonl</code>.</li><li>Backups are encrypted with AES-256-GCM in authenticated chunks; a wrong key, a changed bit, a truncated, extended or reordered file is rejected. A manual backup's key never touches the disk of the machine; the panel hands it only to the session that started the backup, once. Reading a backup is bounded by the sizes its manifest declares, so a crafted file cannot fill the disk or memory, and it is fully authenticated before anything in the install is touched.</li><li>The model endpoint is checked before it is saved: private and local addresses are allowed over plain HTTP (including IPv6 literals such as <code>http://[fd00::1]:8000/v1</code>), anything public needs HTTPS, and cloud metadata addresses (including <code>100.100.100.200</code> and <code>fd00:ec2::254</code>) and special ranges (link-local, multicast, NAT64, 6to4, Teredo, the benchmarking range) are refused. The check connects to the address it validated and does not follow redirects. The stored URL is resolved again when the agents use it, outside the panel's control, so a name that later resolves somewhere else (DNS rebinding) is not caught: use an IP address or a name you control. Do not set <code>NODE_USE_ENV_PROXY=1</code>, or other proxy variables, for the panel's process: they bypass the address pinning of the check. Model names offered from a remote server are filtered to the plain name pattern.</li><li>The panel runs with the NanoClaw user's privileges.</li></ul>\n<h2 id=\"troubleshooting\">Troubleshooting<a class=\"anchor\" href=\"#troubleshooting\" aria-label=\"Link to this section\">#</a></h2>\n<div class=\"table-wrap\"><table><thead><tr><th>Symptom</th><th>Cause and fix</th></tr></thead><tbody><tr><td>NanoClaw prints <em>upgrade tripwire</em> and stops</td><td>The tree changed outside setup. See <a href=\"#after-installing-the-upgrade-check\">After installing: the upgrade check</a>.</td></tr><tr><td>No panel, log says <em>did not start</em></td><td>The log line names the cause: port in use (<code>PANEL_PORT</code>), unreadable certificate files, invalid setting. NanoClaw itself keeps running.</td></tr><tr><td>Panel opens but says <em>host_not_allowed</em> (421)</td><td>The address uses a name that is not local. Add it to <code>PANEL_ALLOWED_HOSTS</code>.</td></tr><tr><td><em>network_not_allowed</em> (403)</td><td>The request came from a public internet address. Intended; see <a href=\"#security-model\">Security model</a>.</td></tr><tr><td><em>origin_mismatch</em></td><td>Behind a proxy or with a different name than expected: set <code>PANEL_PUBLIC_ORIGIN</code>.</td></tr><tr><td>Cannot sign in, <em>login_throttled</em></td><td>Too many wrong passwords from this address (or, rarely, from everywhere). Wait, restart the service to clear the per-address lock, or run <code>scripts/manager-panel.ts unlock</code> for the overall one.</td></tr><tr><td><em>login_busy</em> (429)</td><td>Three password checks are already running. Try again in a second.</td></tr><tr><td><em>setup_in_progress</em> (409)</td><td>The first-run setup was submitted twice at once; one of them went through.</td></tr><tr><td><em>Create backup</em> says a key is pending (<em>backup_key_pending</em>, 409)</td><td>A backup finished in another session and nobody has collected its key yet. Use that session, or wait 15 minutes.</td></tr><tr><td>A restore says <em>restore_in_progress</em> or <em>rollback_failed</em></td><td>Another restore, rollback or commit is running or crashed (remove a stale lock only if the process is gone); see <em>If it is interrupted</em> in <a href=\"#restoring-a-backup\">Restoring a backup</a>.</td></tr><tr><td><em>Create backup</em> seems stuck on the first phase</td><td>It is waiting for agents that are in the middle of a message, up to <code>PANEL_BACKUP_WAIT_SECONDS</code>, then it carries on. The progress bar and the file count show when it is packing.</td></tr><tr><td>Agents fail with <em>Missing key limit.output</em></td><td>An old panel version wrote a context limit without an output limit; apply the model once more from the current panel.</td></tr><tr><td>Agent answers nothing, container log says no <code>&lt;message&gt;</code> blocks</td><td>The model does not follow NanoClaw's reply format. Use a model that follows instructions.</td></tr><tr><td>After a model change an agent still uses the old one</td><td>Its restart failed (look in the host log for <em>Failed to stop session</em>). Run <em>Restart</em> again, or <code>docker rm -f</code> the stuck container.</td></tr><tr><td><em>Provider credentials need the OpenCode and OneCLI skills installed</em></td><td>The helper that stores keys is built on <code>add-opencode</code> and <code>add-onecli</code>. Install them, then apply the panel skill again.</td></tr><tr><td><em>The credential gateway is not reachable</em></td><td>OneCLI is not running. Check it (<code>docker ps</code>) and the <code>ONECLI_URL</code> in <code>.env</code>.</td></tr><tr><td>The ChatGPT sign-in shows no page and code</td><td>Docker is not available to the NanoClaw user, or the agent image is missing. Build it (<code>./container/build.sh build</code>) and retry.</td></tr><tr><td>Apply says <em>credential_missing</em></td><td>The credential for that provider is not stored yet. Save the key or sign in first.</td></tr><tr><td>Restore refuses: <em>host_running</em></td><td>NanoClaw is still running. Stop it first.</td></tr><tr><td>Restore refuses: <em>backup_newer</em></td><td>The backup was made by newer code. Update NanoClaw, then restore.</td></tr><tr><td>Restore warns: <em>not installed on this host</em></td><td>The backup used channels or a gateway this install lacks. Install those skills before starting.</td></tr><tr><td>Verify says <em>wrong key, or the backup is damaged</em></td><td>Wrong key or a damaged file. The two cannot be told apart by design.</td></tr><tr><td>Model check: <em>Could not reach the endpoint</em> from a server on the same machine</td><td>Use the Docker bridge address, and make the server listen on it. See <a href=\"#connecting-an-endpoint\">Connecting an endpoint</a>.</td></tr></tbody></table></div>\n<p>When asking for help, include the NanoClaw log lines around the problem and the request id shown in the error (never the key, the password or the contents of <code>.env</code>).</p>\n<h2 id=\"reference\">Reference<a class=\"anchor\" href=\"#reference\" aria-label=\"Link to this section\">#</a></h2>\n<h3 id=\"settings\">Settings<a class=\"anchor\" href=\"#settings\" aria-label=\"Link to this section\">#</a></h3>\n<p>All optional, in the install's <code>.env</code> (or the environment).</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Setting</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>PANEL_ENABLED</code></td><td><code>true</code></td><td><code>false</code> turns the panel off.</td></tr><tr><td><code>PANEL_BIND</code></td><td><code>127.0.0.1</code></td><td>Address to listen on. <code>0.0.0.0</code> for all interfaces.</td></tr><tr><td><code>PANEL_PORT</code></td><td><code>3200</code></td><td>Port.</td></tr><tr><td><code>PANEL_PUBLIC_ORIGIN</code></td><td>unset</td><td>The exact origin browsers use when behind a proxy, such as <code>https://panel.example.org</code>.</td></tr><tr><td><code>PANEL_ALLOWED_HOSTS</code></td><td>unset</td><td>Comma-separated extra host names accepted.</td></tr><tr><td><code>PANEL_TLS_CERT</code>, <code>PANEL_TLS_KEY</code></td><td>unset</td><td>PEM files to serve HTTPS directly. Set both or neither.</td></tr><tr><td><code>PANEL_ALLOW_PUBLIC</code></td><td><code>false</code></td><td><code>true</code> accepts connections from public internet addresses. Not recommended.</td></tr><tr><td><code>PANEL_BACKUP_DIR</code></td><td><code>~/.local/share/nanoclaw-backups/&lt;install&gt;</code></td><td>Where the panel keeps backups.</td></tr><tr><td><code>PANEL_BACKUP_WAIT_SECONDS</code></td><td><code>60</code></td><td>How long a backup waits for busy agents before going ahead anyway.</td></tr><tr><td><code>MANAGER_BACKUP_DIR</code></td><td>same as above</td><td>Backups folder for the terminal tool.</td></tr><tr><td><code>MANAGER_BACKUP_KEY</code></td><td>unset</td><td>The key for the terminal tool (prefer <code>--key-file</code> or the prompt).</td></tr></tbody></table></div>\n<h3 id=\"terminal-commands\">Terminal commands<a class=\"anchor\" href=\"#terminal-commands\" aria-label=\"Link to this section\">#</a></h3>\n<pre><code class=\"language-text\">scripts/manager-backup.ts create [--machine-identity]\nscripts/manager-backup.ts list\nscripts/manager-backup.ts verify &lt;id|file&gt;\nscripts/manager-backup.ts restore &lt;id|file&gt; [--rehearsal] [--machine-identity] [--yes]\nscripts/manager-backup.ts commit &lt;transaction&gt;\nscripts/manager-backup.ts rollback &lt;transaction&gt;\nscripts/manager-backup.ts prune [--keep-last N] [--keep-monthly N]\nscripts/manager-backup.ts schedule init-key | install [--keep N] [--weekday Sun] [--time HH:MM] | status | remove\nscripts/manager-backup.ts scheduled [--keep N]        (what the timer runs)\n        (all accept --dir &lt;folder&gt; and --key-file &lt;path&gt;)\n\nscripts/manager-panel.ts setup-code | reset-password | revoke-sessions | unlock | status</code></pre>\n<p>Run them as <code>pnpm exec tsx scripts/&lt;name&gt;.ts ...</code>.</p>\n<p>Options can be written <code>--keep 3</code> or <code>--keep=3</code>. An unknown option, or an option that needs a value and has none, stops the command with an error instead of being ignored (a typo such as <code>--rehersal</code> must never turn a rehearsal into a real restore). <code>prune</code> wants whole numbers: <code>--keep-last</code> 1 or more, <code>--keep-monthly</code> 0 or more. A <code>--key-file</code> that other users can read gets a warning; keep it at mode 0600.</p>\n<h3 id=\"files-and-folders\">Files and folders<a class=\"anchor\" href=\"#files-and-folders\" aria-label=\"Link to this section\">#</a></h3>\n<div class=\"table-wrap\"><table><thead><tr><th>Path</th><th>What</th></tr></thead><tbody><tr><td><code>data/manager-panel/</code></td><td>Panel state, private (mode 0700): password hash, login lock, audit log, identifier key, model-change journal. Included in backups.</td></tr><tr><td><code>~/.local/share/nanoclaw-backups/&lt;install&gt;/</code></td><td>Backups (<code>&lt;id&gt;.mbk</code>) and their small description files (<code>&lt;id&gt;.meta.json</code>).</td></tr><tr><td><code>.manager-backup-txn/</code> inside <code>data/</code>, <code>groups/</code>, <code>store/</code></td><td>Rollback copies during a restore; removed by <code>commit</code> or <code>rollback</code>.</td></tr><tr><td><code>src/modules/manager-backup/</code>, <code>src/modules/manager-panel/</code></td><td>The skills' code.</td></tr></tbody></table></div>\n<h3 id=\"http-api\">HTTP API<a class=\"anchor\" href=\"#http-api\" aria-label=\"Link to this section\">#</a></h3>\n<p>For the curious or for scripting. Everything is under <code>/api/v1</code>, JSON, <code>Cache-Control: no-store</code>. State-changing calls need the cookie, the <code>X-CSRF-Token</code> header and an <code>Origin</code> equal to the panel's.</p>\n<div class=\"table-wrap\"><table><thead><tr><th>Method and path</th><th>Needs password again</th><th>What</th></tr></thead><tbody><tr><td><code>GET /health</code></td><td>no</td><td><code>{&quot;status&quot;:&quot;ok&quot;}</code>, no session needed</td></tr><tr><td><code>GET /setup</code>, <code>POST /setup</code></td><td>no</td><td>first-run status; create the administrator</td></tr><tr><td><code>POST /session</code>, <code>GET /session</code>, <code>DELETE /session</code></td><td>no</td><td>sign in, read session, sign out</td></tr><tr><td><code>POST /session/reauth</code></td><td>no</td><td>type the password again</td></tr><tr><td><code>GET /overview</code>, <code>GET /agents</code>, <code>GET /channels</code></td><td>no</td><td>read</td></tr><tr><td><code>POST /agents/{id}/restart</code></td><td>no</td><td>restart an agent</td></tr><tr><td><code>GET /model</code></td><td>no</td><td>current model settings</td></tr><tr><td><code>POST /model/preflight</code></td><td>no</td><td>check a provider choice (<code>kind</code>: <code>compatible</code>, <code>chatgpt</code> or <code>claude</code>); <code>images</code> (true or false) is the image choice, and the answer's <code>image_support</code> is what the endpoint says</td></tr><tr><td><code>POST /model/apply</code></td><td>yes</td><td>apply it to all agents</td></tr><tr><td><code>GET /credentials</code></td><td>no</td><td>which provider credentials are stored (booleans)</td></tr><tr><td><code>POST /credentials/claude</code>, <code>POST /credentials/openai-key</code></td><td>yes</td><td>store a key or token; nothing is returned</td></tr><tr><td><code>DELETE /credentials/claude</code>, <code>/openai-key</code>, <code>/chatgpt-login</code></td><td>yes</td><td>remove a stored credential; refused with 409 while in use</td></tr><tr><td><code>POST</code>, <code>GET</code>, <code>DELETE /credentials/chatgpt/login</code></td><td>start: yes</td><td>ChatGPT device sign-in: start, poll for page and code, cancel</td></tr><tr><td><code>GET /phone</code></td><td>no</td><td>the phone app's state: connection, address, whether a token is set (never the token)</td></tr><tr><td><code>POST /phone/token</code></td><td>yes</td><td>make a new token; it is returned once</td></tr><tr><td><code>POST /phone/pairing</code>, <code>DELETE /phone/pairing</code></td><td>start: yes</td><td>make the pairing QR code (returned once, as rows of 0 and 1) or cancel the waiting one</td></tr><tr><td><code>POST /phone/enabled</code></td><td>yes</td><td>turn the voice channel on or off (<code>{&quot;enabled&quot;: true}</code>); takes effect at the next start</td></tr><tr><td><code>GET /backups</code></td><td>no</td><td>list</td></tr><tr><td><code>POST /backups</code></td><td>yes</td><td>start a backup in the background (<code>202</code>); <code>force</code> is ignored</td></tr><tr><td><code>GET /backups/job</code></td><td>no</td><td>progress of the backup; once it is done, its key, one time only</td></tr><tr><td><code>POST /backups/{id}/verify</code></td><td>no</td><td>verify with a key</td></tr><tr><td><code>GET /backups/{id}/download</code></td><td>yes</td><td>the encrypted file</td></tr><tr><td><code>DELETE /backups/{id}</code></td><td>yes</td><td>delete</td></tr></tbody></table></div>\n<h2 id=\"known-limits\">Known limits<a class=\"anchor\" href=\"#known-limits\" aria-label=\"Link to this section\">#</a></h2>\n<ul><li>One provider for all agents; a different provider per agent is not offered.</li><li>The panel cannot check a ChatGPT or Claude model name, because the keys live in the gateway.</li><li>The ChatGPT sign-in and the Claude credential were tested against the real gateway and, for the sign-in, against OpenAI's real pairing page, but not completed with a real account.</li><li>Restoring and updating are terminal-only.</li><li>Credentials in the gateway are not part of backups.</li><li>The panel starts and stops with NanoClaw; it cannot start NanoClaw.</li><li>A restart requested from the panel is reported as done even if a stuck container could not be removed; check the log if an agent keeps its old behaviour.</li><li>Tested on a single Debian 13 host with one agent and a mock model server. Channels, several machines and long-running installs have not been exercised.</li><li>The guide's nginx example, <code>/update-nanoclaw</code> followed by re-applying the skills, and applying the skills with the <code>/add-manager-*</code> commands in Claude Code have not been tried end to end.</li></ul>\n</main>\n</div>\n</body>\n</html>\n"; // privacy-scan: allow -- generated; docs/guide.md carries its own markers
